function useAnim(){
  useEffect(()=>{
    const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('v');}),{threshold:0.04});
    document.querySelectorAll('.au').forEach(el=>o.observe(el));
    return()=>o.disconnect();
  },[]);
}
