function CountUp({value}){
  const ref=useRef(null);
  const[disp,setDisp]=useState(value);
  useEffect(()=>{
    const m=String(value).match(/^(\D*)(\d+(?:\.\d+)?)(.*)$/);
    if(!m){setDisp(value);return;}
    const pre=m[1],target=parseFloat(m[2]),suf=m[3];
    const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion:reduce)').matches;
    if(reduce){setDisp(value);return;}
    let started=false;
    const o=new IntersectionObserver(es=>es.forEach(e=>{
      if(e.isIntersecting&&!started){started=true;
        const dur=1300,t0=performance.now();
        const step=(now)=>{const p=Math.min((now-t0)/dur,1);const eased=1-Math.pow(1-p,3);
          setDisp(pre+Math.round(target*eased)+suf);
          if(p<1)requestAnimationFrame(step);else setDisp(pre+Math.round(target)+suf);};
        requestAnimationFrame(step);
      }
    }),{threshold:0.5});
    if(ref.current)o.observe(ref.current);
    return()=>o.disconnect();
  },[value]);
  return <span ref={ref}>{disp}</span>;
}

function Progress(){
  const[p,setP]=useState(0);
  useEffect(()=>{const fn=()=>{const h=document.body.scrollHeight-window.innerHeight;setP(h>0?(window.scrollY/h)*100:0);};window.addEventListener('scroll',fn);return()=>window.removeEventListener('scroll',fn);},[]);
  return <div style={{position:'fixed',top:0,left:0,height:'2px',width:p+'%',background:'linear-gradient(to right,#C9A84C,#E8C96A)',zIndex:200,transition:'width 0.1s'}}/>;
}

