function Lightbox({lb,setLb}){
  useEffect(()=>{
    if(!lb)return;
    const onKey=(e)=>{
      if(e.key==='Escape')setLb(null);
      else if(e.key==='ArrowRight')setLb(v=>v&&{...v,index:(v.index+1)%v.pages.length});
      else if(e.key==='ArrowLeft')setLb(v=>v&&{...v,index:(v.index-1+v.pages.length)%v.pages.length});
    };
    window.addEventListener('keydown',onKey);
    document.body.style.overflow='hidden';
    return()=>{window.removeEventListener('keydown',onKey);document.body.style.overflow='';};
  },[lb,setLb]);
  if(!lb)return null;
  const prev=(e)=>{e.stopPropagation();setLb(v=>({...v,index:(v.index-1+v.pages.length)%v.pages.length}));};
  const next=(e)=>{e.stopPropagation();setLb(v=>({...v,index:(v.index+1)%v.pages.length}));};
  return(
    <div role="dialog" aria-modal="true" aria-label={lb.title} onClick={()=>setLb(null)} style={{position:'fixed',inset:0,zIndex:300,background:'rgba(3,3,3,0.94)',backdropFilter:'blur(8px)',display:'flex',alignItems:'center',justifyContent:'center',padding:'72px 20px'}}>
      <div style={{position:'absolute',top:'22px',left:'6%',right:'6%',display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:'16px'}}>
        <div>
          <div style={{fontFamily:"'Playfair Display',serif",fontSize:'17px',fontWeight:700,color:W}}>{lb.title}</div>
          <div style={{fontFamily:"'Raleway',sans-serif",fontSize:'9px',color:'rgba(201,168,76,0.65)',letterSpacing:'2px',textTransform:'uppercase',marginTop:'4px'}}>{lb.index+1} / {lb.pages.length}</div>
        </div>
        <button onClick={(e)=>{e.stopPropagation();setLb(null);}} aria-label="Close viewer" style={{fontFamily:"'Raleway',sans-serif",fontSize:'10px',color:'rgba(255,255,255,0.75)',letterSpacing:'2px',textTransform:'uppercase',border:'1px solid '+GB,padding:'9px 15px',borderRadius:'2px',background:'rgba(3,3,3,0.5)'}}>Close ✕</button>
      </div>
      <img src={lb.pages[lb.index]} alt={lb.title+', page '+(lb.index+1)} onClick={(e)=>e.stopPropagation()} style={{maxWidth:'min(980px,92vw)',maxHeight:'78vh',objectFit:'contain',border:'1px solid '+GB,borderRadius:'3px',boxShadow:'0 30px 90px rgba(0,0,0,0.7)'}}/>
      {lb.pages.length>1&&<>
      <button onClick={prev} aria-label="Previous page" style={{position:'absolute',left:'3%',top:'50%',transform:'translateY(-50%)',fontSize:'24px',color:W,width:'52px',height:'52px',borderRadius:'50%',border:'1px solid '+GB,background:'rgba(3,3,3,0.6)'}}>‹</button>
      <button onClick={next} aria-label="Next page" style={{position:'absolute',right:'3%',top:'50%',transform:'translateY(-50%)',fontSize:'24px',color:W,width:'52px',height:'52px',borderRadius:'50%',border:'1px solid '+GB,background:'rgba(3,3,3,0.6)'}}>›</button>
      </>}
      <div style={{position:'absolute',bottom:'24px',fontFamily:"'Raleway',sans-serif",fontSize:'9px',color:'rgba(255,255,255,0.4)',letterSpacing:'2px',textTransform:'uppercase'}}>Arrow keys to flip · Esc to close</div>
    </div>
  );
}

function CountNum({value,prefix,suffix,dec}){
  const p0=prefix||'',s0=suffix||'',d0=dec||0;
  const ref=useRef(null);
  const fmt=(n)=>p0+(d0?n.toFixed(d0):Math.round(n).toLocaleString())+s0;
  const[disp,setDisp]=useState(fmt(0));
  useEffect(()=>{
    const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion:reduce)').matches;
    if(reduce){setDisp(fmt(value));return;}
    let started=false;
    const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting&&!started){started=true;
      const dur=1300,t0=performance.now();
      const step=(now)=>{const pr=Math.min((now-t0)/dur,1);const eased=1-Math.pow(1-pr,3);
        setDisp(fmt(value*eased));if(pr<1)requestAnimationFrame(step);else setDisp(fmt(value));};
      requestAnimationFrame(step);}}),{threshold:0.5});
    if(ref.current)o.observe(ref.current);return()=>o.disconnect();
  },[value]);
  return <span ref={ref}>{disp}</span>;
}

function CaseChart({points,from,to,label}){
  const ref=useRef(null);const[on,setOn]=useState(false);
  useEffect(()=>{
    const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion:reduce)').matches;
    if(reduce){setOn(true);return;}
    const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)setOn(true);}),{threshold:0.35});
    if(ref.current)o.observe(ref.current);return()=>o.disconnect();
  },[]);
  const W=700,H=210,pad=26;
  const max=Math.max(...points),min=Math.min(...points);
  const xs=points.map((_,i)=>pad+i*(W-2*pad)/(points.length-1));
  const ys=points.map(v=>H-pad-((v-min)/((max-min)||1))*(H-2*pad));
  const line=xs.map((x,i)=>(i?'L':'M')+x.toFixed(1)+' '+ys[i].toFixed(1)).join(' ');
  const area=line+' L'+xs[xs.length-1].toFixed(1)+' '+(H-pad)+' L'+xs[0].toFixed(1)+' '+(H-pad)+' Z';
  return(
    <div ref={ref} style={{width:'100%'}}>
      <svg viewBox={'0 0 '+W+' '+H} style={{width:'100%',height:'auto',display:'block'}} role="img" aria-label={label+', from '+from+' to '+to}>
        <defs><linearGradient id="cg" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="rgba(201,168,76,0.28)"/><stop offset="100%" stopColor="rgba(201,168,76,0)"/></linearGradient></defs>
        <path d={area} fill="url(#cg)" opacity={on?1:0} style={{transition:'opacity 0.9s ease 0.5s'}}/>
        <path d={line} fill="none" stroke="#C9A84C" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{strokeDasharray:1600,strokeDashoffset:on?0:1600,transition:'stroke-dashoffset 1.4s ease'}}/>
        {xs.map((x,i)=>(<circle key={i} cx={x} cy={ys[i]} r="3.5" fill="#040404" stroke="#C9A84C" strokeWidth="2" opacity={on?1:0} style={{transition:'opacity 0.3s ease '+(0.4+i*0.18)+'s'}}/>))}
      </svg>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginTop:'6px'}}>
        <span style={{fontFamily:"'Raleway',sans-serif",fontSize:'10px',color:'rgba(255,255,255,0.4)',letterSpacing:'1px'}}>{from}</span>
        <span style={{fontFamily:"'Raleway',sans-serif",fontSize:'9px',color:'rgba(201,168,76,0.55)',letterSpacing:'2px',textTransform:'uppercase'}}>{label}</span>
        <span style={{fontFamily:"'Playfair Display',serif",fontSize:'15px',fontWeight:700,color:G}}>{to}</span>
      </div>
    </div>
  );
}

